    sections: [
      { title: "Hipótesis y definición", paragraphs: ["La hipótesis propone que ciertos descensos relativamente extremos pueden corregir parcialmente hacia un promedio reciente. No presupone que el precio tenga un valor justo fijo ni que siga una distribución normal. En EUR/USD simulado con barras horarias UTC y precios medios, se calculan media μ y desviación estándar poblacional σ de los veinte cierres anteriores a t. La distancia normalizada es z igual a cierre t menos μ, dividido entre σ. Si σ es cero o faltan datos, no hay señal. Usar la desviación como escala hace comparables distancias relativas, pero no asigna automáticamente una probabilidad a cada valor de z."] },
      { title: "Condición y entrada posterior", paragraphs: ["La única dirección estudiada es larga: z debe pasar de un valor superior a menos dos en t menos uno a un valor igual o inferior a menos dos en t. Cada z utiliza sus veinte cierres anteriores correspondientes. Se entra en la apertura siguiente si continúa por debajo de μ y está como máximo a cinco pips del cierre de señal. μ y σ se congelan con la ventana de t para toda la operación. No se compra en el mínimo de la señal ni se añaden unidades si el precio sigue cayendo. Solo se permite una posición y se registran todos los descartes."] },
      { title: "Salidas y riesgo explícito", paragraphs: ["El objetivo es la media μ congelada. El stop se sitúa una distancia de una vez y media σ bajo la entrada, expresando σ en unidades de precio. También se cierra en la apertura posterior a seis barras completas desde la entrada si no hubo otra salida. Se toma la primera condición aplicable y se rechaza una operación cuyo beneficio al objetivo sea nulo o negativo tras dos pips de fricción agregada. La pérdida prevista incluye stop y esos costes, con máximo de 0,25 % del patrimonio ficticio. La media no se persigue desplazando el objetivo y nunca se amplía el stop."] },
      { title: "Fallos de la idea", paragraphs: ["Una caída puede ser el inicio de una tendencia y hacer que los extremos estadísticos persistan. Si la volatilidad aumenta, la escala histórica puede subestimar movimientos posteriores. Un valor z bajo no significa ganga ni que la probabilidad de rebote sea conocida. Los saltos adversos se ejecutan al primer precio disponible peor y se añaden costes; una barra que toca ambas salidas sin secuencia se resuelve primero al stop. Dos pips constantes son solo un modelo didáctico, sometido a sensibilidad. Promediar una pérdida añadiría una estrategia diferente, con más riesgo, y está expresamente prohibido en este protocolo educativo."] },
      { title: "Prueba y ejercicio", paragraphs: ["Calcula μ, σ y z en una pequeña serie sintética, ocultando las barras siguientes hasta haber registrado la señal. Comprueba que añadir datos futuros no cambia decisiones antiguas. En una evaluación cronológica separada conserva todos los extremos, incluidos los que continuaron cayendo; no selecciones únicamente rebotes completos. Revisa expectativas netas, duración, drawdown y dependencia de eventos extremos. Cambiar ventana o umbral tras observar resultados cuenta como una nueva variante y requiere otra evaluación. Si la aparente ventaja depende de suponer ejecución perfecta o de excluir tendencias identificadas después, descarta esa interpretación. La observación prospectiva debe mantenerse simulada y no presentarse como protección del capital."] },
    ],
    workedExample: { title: "Desviación ficticia de dos sigmas", scenario: "Media previa μ = 1,1000 y σ = 0,0010, equivalentes a 10 pips. Cierre t = 1,0980, z previo mayor que −2. Entrada siguiente: 1,0981; valor 1 USD/pip.", steps: ["z = (1,0980 − 1,1000)/0,0010 = −2.", "Distancia stop = 1,5 × 10 = 15 pips; stop = 1,0966; objetivo congelado = 1,1000.", "Ganancia de precio objetivo = 19 pips; neta = 19 − 2 = 17 USD. Riesgo previsto = 15 + 2 = 17 USD.", "Objetivo neto = 1 R; si el precio sigue cayendo no se añade volumen para mejorar el precio medio."], conclusion: "z mide distancia respecto a una ventana pasada. No demuestra que volver a la media sea probable ni rentable." },
    commonMistakes: [{ mistake: "z = −2 asegura un rebote con una probabilidad universal.", correction: "No asumir normalidad ni estabilidad; medir resultados bajo reglas concretas." }, { mistake: "Añadir posición cada vez que el precio se aleja más.", correction: "Mantener una sola entrada y presupuesto fijo según este protocolo." }], summary: ["Media y dispersión se calculan antes de la barra evaluada.", "Objetivo y escala quedan congelados en la entrada.", "Una tendencia puede mantener o ampliar la desviación."], relatedConcepts: ["Mean reversion", "Z-score", "Desviación estándar", "Estacionariedad"], sources: [averages, plan, forex],
    diagram: { title: "Distancia normalizada y salida", nodes: ["20 cierres anteriores → μ y σ", "z cruza −2", "Apertura siguiente", "Objetivo μ / stop 1,5σ", "Salida temporal o de precio"], caption: "La escala histórica no implica una distribución normal ni garantiza retorno al promedio." },
    questions: [
      { type: "number", concept: "Z-score", prompt: "Cierre 1,0980, media 1,1000 y σ 0,0010: ¿z?", answer: -2, tolerance: 0.001, required: true, explanation: "(1,0980 − 1,1000)/0,0010 = −2." },
      { type: "choice", concept: "Media", prompt: "¿Qué media usa el objetivo de esta operación?", options: ["La congelada con los datos previos a la señal", "La media futura que más convenga", "Una media desplazada para evitar cerrar"], answer: "La congelada con los datos previos a la señal", explanation: "El objetivo debe quedar definido con la información disponible y no cambiar retrospectivamente." },
      { type: "boolean", concept: "Normalidad", prompt: "Expresar una distancia en desviaciones estándar demuestra normalidad de precios.", answer: "false", explanation: "La estandarización es un cálculo; la forma de la distribución requiere evidencia distinta." },
      { type: "text", concept: "Dispersión", prompt: "Si σ es cero, el protocolo debe ____ la señal.", answer: "descartar", acceptedAnswers: ["descartar", "cancelar", "rechazar"], explanation: "Dividir entre cero no produce un z válido y no hay señal evaluable." },
      { type: "choice", concept: "Riesgo", prompt: "Si el descenso continúa, ¿qué permite este protocolo?", options: ["Respetar salida y presupuesto sin añadir unidades", "Duplicar compras hasta recuperar", "Eliminar el stop porque la media atrae"], answer: "Respetar salida y presupuesto sin añadir unidades", explanation: "Promediar a la baja no forma parte de las reglas y aumenta una exposición diferente." },
    ],
